mapper.select:


    and s.sequence_name like concat('%', #{sequenceName}, '%')
    and s.status = #{status}

order by s.sequence_id

mapper.delete:
with e as (delete from abr_nurture_enrollment where sequence_id = #{sequenceId}),
     t as (delete from abr_nurture_step where sequence_id = #{sequenceId})
delete from abr_nurture_sequence where sequence_id = #{sequenceId}

mapper.select:


    and e.sequence_id = #{sequenceId}
    and e.status = #{status}
    and e.target_type = #{targetType}
    and e.target_id = #{targetId}

order by case e.status when 'waiting_confirm' then 0 when 'active' then 1 else 2 end, e.next_due_time, e.enrollment_id desc


where e.status = 'active' and s.status = '0' and e.next_due_time <= #{now}
order by e.next_due_time
limit #{limit}

select tier_snapshot as "tier", count(*) as "count"
from abr_plan_item
where visitor_id = #{visitorId}
or app_user_id = #{appUserId}
group by tier_snapshot
